/* app41.js - blog interactive CSS: shayari blocks + 6 reading themes + BOOK MODE + paragraphs. DO NOT EDIT. */
(function () {
  "use strict";
  if (window.SM_BLOG_THEME_CSS) return;
  window.SM_BLOG_THEME_CSS = true;
  var css = document.createElement("style");
  css.textContent = ".blog-themes{display:flex;align-items:center;gap:7px;margin:0 0 16px;padding:0 0 12px;border-bottom:1px dashed var(--border);flex-wrap:wrap}.blog-themes span{font-family:'JetBrains Mono',monospace;font-size:.62rem;text-transform:uppercase;letter-spacing:.08em;color:var(--muted);margin-right:2px}.bt-dot{width:21px;height:21px;border-radius:50%;border:2px solid var(--border);cursor:pointer;transition:transform .15s ease,box-shadow .15s ease;flex:none}.bt-dot:hover{transform:scale(1.18)}.bt-dot.sel{border-color:var(--accent);box-shadow:0 0 0 3px rgba(124,92,255,.25)}.bt-book{margin-left:auto;padding:4px 12px;border-radius:999px;border:1px solid var(--border);background:var(--bg);color:var(--text);font-family:'JetBrains Mono',monospace;font-size:.66rem;font-weight:600;cursor:pointer;transition:background .2s ease}.bt-book:hover{border-color:var(--accent);color:var(--accent)}.bt-book.on{background:var(--grad-btn);color:#fff;border-color:transparent}.blog-art-body{color:var(--text)}.blog-art-body strong{color:var(--accent);font-weight:700}.blog-art-txt{white-space:normal}.blog-art-txt p{margin:0 0 12px}.blog-art-txt h3{font-size:1.12rem;margin:24px 0 10px;font-weight:800;letter-spacing:.01em;background:var(--grad-ink);-webkit-background-clip:text;background-clip:text;color:transparent}.blog-shayari{margin:18px 0;padding:14px 18px;border-left:3px solid var(--accent);border-radius:0 14px 14px 0;background:linear-gradient(135deg,rgba(124,92,255,.09),rgba(255,94,120,.09));font-style:italic;line-height:2.05}.blog-shayari .bs-q{font-style:normal;font-size:1.35rem;margin-right:9px;color:var(--accent)}.blog-article{transition:background .2s ease,border-color .2s ease}.blog-pghold{display:none}.blog-page{display:none}.blog-page.on{display:block;animation:pgturn .45s ease}@keyframes pgturn{from{opacity:0;transform:perspective(900px) rotateY(-14deg) translateX(22px)}to{opacity:1;transform:none}}.blog-bookbar{display:flex;align-items:center;justify-content:center;gap:12px;margin-top:16px;padding-top:12px;border-top:1px dashed var(--border)}.bb-btn{padding:8px 16px;border-radius:10px;border:1px solid var(--border);background:var(--bg);color:var(--text);cursor:pointer;font-size:.78rem;font-weight:600}.bb-btn:hover:not(:disabled){border-color:var(--accent);color:var(--accent)}.bb-btn:disabled{opacity:.35;cursor:default}.bb-count{font-family:'JetBrains Mono',monospace;font-size:.68rem;color:var(--muted)}.btheme-sep{background:#f8f1e3!important;border-color:#e2d5bb!important}.btheme-sep .blog-art-body,.btheme-sep .blog-art-txt{color:#4a3f30!important}.btheme-sep .blog-art-title{color:#7c5c2e!important;background:none!important;-webkit-text-fill-color:#7c5c2e}.btheme-night{background:#12141c!important;border-color:#2a2e3d!important}.btheme-night .blog-art-body,.btheme-night .blog-art-txt{color:#d5d9e6!important}.btheme-night .blog-art-title{color:#9db4ff!important;background:none!important;-webkit-text-fill-color:#9db4ff}.btheme-forest{background:#eaf3ea!important;border-color:#c4dcc4!important}.btheme-forest .blog-art-body,.btheme-forest .blog-art-txt{color:#27401f!important}.btheme-forest .blog-art-title{color:#2e6b34!important;background:none!important;-webkit-text-fill-color:#2e6b34}.btheme-ocean{background:#e7f1f8!important;border-color:#bcd6e8!important}.btheme-ocean .blog-art-body,.btheme-ocean .blog-art-txt{color:#1c3a52!important}.btheme-ocean .blog-art-title{color:#1d5d8c!important;background:none!important;-webkit-text-fill-color:#1d5d8c}.btheme-rose{background:#fdeef2!important;border-color:#eccbd6!important}.btheme-rose .blog-art-body,.btheme-rose .blog-art-txt{color:#5c2338!important}.btheme-rose .blog-art-title{color:#b0345f!important;background:none!important;-webkit-text-fill-color:#b0345f}";
  document.head.appendChild(css);
})();
